#include <vector>

class Solution {
public:
    int bitwiseOrOfEven(std::vector<int>& nums) {
        int ans = 0;
        for (int x : nums) {
            if (x % 2 == 0) ans |= x;
        }
        return ans;
    }
};

class Solution {
    public int bitwiseOrOfEven(int[] nums) {
        int ans = 0;
        for (int x : nums) {
            if (x % 2 == 0) ans |= x;
        }
        return ans;
    }
}

var bitwiseOrOfEven = function(nums) {
    let ans = 0;
    for (const x of nums) {
        if (x % 2 === 0) ans |= x;
    }
    return ans;
};
